<div data-billing-balances><div class="portal-card-head"><div><strong>Balans ve borclar</strong><small>Abonent uzre borc, odenis ve aktiv xidmet veziyyeti.</small></div></div><form class="billing-filter" method="get" action="billing-balances.php" data-billing-filter><div class="portal-form-row"><label>Axtaris</label><input type="search" name="search" value="<?= e((string) ($query['search'] ?? '')); ?>" placeholder="Kod, muqavile, ad, telefon"></div><div class="portal-form-row"><label>Balans</label><select name="status"><option value="">Hamisi</option><option value="debt"<?= ($query['status'] ?? '') === 'debt' ? ' selected' : ''; ?>>Borclu</option><option value="clear"<?= ($query['status'] ?? '') === 'clear' ? ' selected' : ''; ?>>Borcsuz</option></select></div><button class="portal-primary-btn" type="submit">Tetbiq et</button></form><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Abonent</th><th>Elaqe</th><th>Paket</th><th>Borc</th><th>Cemi odenis</th><th>Aktiv xidmet</th><th>Bitme</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr data-billing-row><td><strong><a href="billing-customer-profile.php?id=<?= e((string) ($row['id'] ?? 0)); ?>"><?= e((string) ($row['subscriber_code'] ?? '-')); ?></a></strong><br><small><?= e((string) ($row['full_name'] ?? '-')); ?></small></td><td><?= e((string) ($row['phone'] ?? '-')); ?><br><small><?= e((string) ($row['area'] ?? '-')); ?></small></td><td><?= e((string) ($row['plan'] ?? '-')); ?></td><td><strong><?= e(number_format((float) ($row['debt_amount'] ?? 0), 2, '.', ' ')); ?> AZN</strong></td><td><?= e(number_format((float) ($row['paid_total'] ?? 0), 2, '.', ' ')); ?> AZN</td><td><?= e((string) ($row['active_service_count'] ?? 0)); ?></td><td><?= e((string) ($row['expires_at'] ?? '-')); ?></td></tr><?php endforeach; ?><?php if ($rows === []): ?><tr><td colspan="7" class="billing-empty">Balans qeydi tapilmadi.</td></tr><?php endif; ?></tbody></table></div><?php require __DIR__ . '/_pagination.p